import{at as e,it as t,n,vt as r}from"./chunks/framework.CsjHfu6k.js";var i=JSON.parse(`{"title":"2026.10.25 Magisk v31.1","description":"","frontmatter":{},"headers":[],"relativePath":"releases/31100.md","filePath":"releases/31100.md","lastUpdated":1792939073000}`),a={name:`releases/31100.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="_2026-10-25-magisk-v31-1" tabindex="-1">2026.10.25 Magisk v31.1 <a class="header-anchor" href="#_2026-10-25-magisk-v31-1" aria-label="Permalink to “2026.10.25 Magisk v31.1”">​</a></h1><p>此版本为 Googlebook（Aluminium OS）带来了官方支持，包括自动建议固件下载，以及将 recovery GPT 映像直接修补到已连接的 USB 驱动器的能力。将 Magisk 引入 Googlebook 还意味着支持 Android 的无头系统用户模式（HSUM）：在该模式下，用户 <code>0</code> 严格作为非交互式后台系统用户运行，而真人用户则在次要用户配置文件中运行。适配 HSUM 带来了若干架构挑战，因为许多长期存在的功能和内部机制都建立在“用户 <code>0</code> 始终是主要交互用户”的假设之上。</p><p>为了解决这个问题，向应用授予超级用户权限的方式已被重新设计，传统的交互式 root 请求提示已被移除。现有的响应式 <code>su</code> 请求流程依赖于在后台守护进程中拦截 root 调用，并在正确的用户会话中启动阻塞式 UI 提示，这与 HSUM 从根本上不兼容，尤其是在处理 <code>adb shell</code> 等不属于前台用户的非应用 UID 时。现在，超级用户权限改为提前在 Magisk app 的“超级用户”选项卡中明确授予应用。</p><p>最后，应用隐藏（包重新打包）功能也已被移除。与交互式 <code>su</code> 提示一样，重新打包和占位管理机制与 HSUM 从根本上不兼容。更重要的是，在 Android 上真正让已安装的包无法被检测在技术上几乎是不可能的。由于交互式 root 提示不再需要 Magisk app 在运行时保持安装，而且 Magisk 也不再在应用缺失时自动重新安装它，因此隐藏 Magisk app 最有效的方法就是在配置好超级用户策略和模块后直接卸载它。</p><ul><li>[General] 支持无头系统用户模式（HSUM）设备</li><li>[General] 放弃对 Android 6.0 的支持；Android 7.0 现在是支持的最低版本</li><li>[General] 移除应用隐藏（重新打包）功能和占位应用；Magisk 不再在应用缺失时自动重新安装</li><li>[App] 移除响应式超级用户请求提示；超级用户访问权限现在在“超级用户”选项卡中提前明确授予</li><li>[App] 统一本地文件和远程 URL 的映像修补流程，涵盖原始映像、OTA zip、出厂映像 zip、三星 Odin tar 和 Aluminium OS recovery GPT 映像</li><li>[App] 自动为 Google Pixel 和 Googlebook（Aluminium OS）设备建议官方固件下载</li><li>[App] 在 Googlebook 上支持修补 Aluminium OS recovery 映像并直接写入已连接的 USB 驱动器</li><li>[App] 在下载和修补映像时显示实时原地读/写进度和传输速度</li><li>[MagiskSU] 移除过时的超级用户访问模式和重新认证设置</li><li>[MagiskSU] 修复 <code>-g</code>/<code>-G</code> 参数处理，将未知选项转发给 shell，并修复守护进程执行信号处理</li><li>[MagiskBoot] 原生支持对 ChromeOS 启动映像签名，并在重新打包时自动重新签名，移除外部 <code>futility</code> 二进制文件</li><li>[MagiskBoot] 使用 ASN.1 DER 编码修复 AVB 1.0 ECDSA 签名验证和签名</li><li>[MagiskBoot] 在启动映像重新打包期间保留三星 <code>SignerVer02</code> 签名</li><li>[MagiskBoot] 撤销重新打包时更新 AVB 哈希描述符映像大小的更改</li><li>[MagiskBoot] 为 XZ 压缩启用架构特定的 BCJ 过滤器，并改进 <code>zImage</code> 压缩载荷检测</li><li>[MagiskBoot] 支持在 Linux 和 macOS 主机上原生构建 <code>magiskboot</code></li><li>[Core] 修复处理 <code>NULL</code> 数据库字符串或守护进程连接失败时的潜在崩溃</li></ul><details class="details custom-block"><summary>英文原版</summary><ul><li>[General] Support Headless System User Mode (HSUM) devices</li><li>[General] Drop support for Android 6.0; Android 7.0 is now the minimum supported version</li><li>[General] Remove the app hiding (repackaging) feature and the stub app; Magisk no longer reinstalls the app automatically if it is missing</li><li>[App] Remove reactive superuser request prompts; superuser access is now explicitly granted ahead of time in the Superuser tab</li><li>[App] Unify the image patching pipeline across local files and remote URLs for raw images, OTA zips, factory image zips, Samsung Odin tars, and Aluminium OS recovery GPT images</li><li>[App] Automatically suggest official firmware downloads for Google Pixel and Googlebook (Aluminium OS) devices</li><li>[App] Support patching Aluminium OS recovery images and writing directly to a connected USB drive on Googlebooks</li><li>[App] Display real-time in-place read/write progress and transfer speeds when downloading and patching images</li><li>[MagiskSU] Remove obsolete superuser access mode and reauthentication settings</li><li>[MagiskSU] Fix <code>-g</code>/<code>-G</code> argument handling, forward unknown options to the shell, and fix daemon exec signal handling</li><li>[MagiskBoot] Support signing ChromeOS boot images natively and automatically re-sign on repack, removing the external <code>futility</code> binary</li><li>[MagiskBoot] Fix AVB 1.0 ECDSA signature verification and signing by using ASN.1 DER encoding</li><li>[MagiskBoot] Preserve Samsung <code>SignerVer02</code> signatures during boot image repack</li><li>[MagiskBoot] Revert updating AVB hash descriptor image size on repack</li><li>[MagiskBoot] Enable architecture-specific BCJ filters for XZ compression and improve <code>zImage</code> compressed payload detection</li><li>[MagiskBoot] Support building <code>magiskboot</code> natively on Linux and macOS hosts</li><li>[Core] Fix potential crashes when handling <code>NULL</code> database strings or failed daemon connections</li></ul></details><p><strong>完整更新日志： <a href="/MagiskChineseDocument/changes.html">这里</a></strong></p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};